<script setup>
import { Head, router } from '@inertiajs/vue3'; import { ref } from 'vue'; import AppLayout from '../Layouts/AppLayout.vue';
const props=defineProps({budget:Object,records:Object}); const initial=ref(props.budget.initial_amount); const form=ref({type:'Egreso'}); function initialize(){router.post('/presupuesto-revolvente/inicializar',{initial_amount:initial.value})} function save(){router.post('/presupuesto-revolvente',form.value)} function sync(){router.post('/presupuesto-revolvente/sincronizar')} function remove(id){router.delete(`/presupuesto-revolvente/${id}`)}
</script>
<template><Head title="Presupuesto Revolvente"/><AppLayout><main class="module-page"><div class="module-header"><div><h2>Presupuesto Revolvente</h2><p>Inicial: L {{budget.initial_amount}} · Saldo: L {{budget.current_balance}}</p></div><div><button class="row-action" @click="sync">Sincronizar fuentes</button><a class="row-action" href="/presupuesto-revolvente/export/pdf">PDF</a><a class="row-action" href="/presupuesto-revolvente/export/xlsx">XLSX</a></div></div><form class="module-toolbar" @submit.prevent="initialize"><input v-model="initial" type="number" min="0" required><button class="row-action">Actualizar monto inicial</button></form><form class="module-form" @submit.prevent="save"><input v-model="form.moved_at" required type="date"><select v-model="form.type"><option>Ingreso</option><option>Egreso</option></select><input v-model="form.concept" required placeholder="Concepto"><input v-model="form.reference" placeholder="Referencia"><input v-model="form.amount" required type="number" min="0.01" placeholder="Monto"><button class="module-primary">Registrar movimiento</button></form><div class="module-table-wrap"><table class="module-table"><tr><th>Fecha</th><th>Tipo</th><th>Concepto</th><th>Monto</th><th>Saldo</th><th></th></tr><tr v-for="row in records.data" :key="row.id"><td>{{row.moved_at}}</td><td>{{row.type}}</td><td>{{row.concept}}</td><td>{{row.amount}}</td><td>{{row.balance_after}}</td><td><button v-if="!row.synchronized" class="row-action delete" @click="remove(row.id)">Eliminar</button></td></tr></table></div></main></AppLayout></template>
